{{ config(materialized='view') }}

SELECT
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  p.category,
  p.subcategory,
  p.supplier_id,
  p.supplier_name,
  COUNT(*) AS ranged_cells,
  SUM(CAST(f.is_in_stock AS INT)) AS in_stock_cells,
  CAST(SUM(CAST(f.is_in_stock AS INT)) AS DOUBLE) / NULLIF(CAST(COUNT(*) AS DOUBLE), 0) AS stock_availability
FROM {{ ref('fact_inventory') }} AS f
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = f.retail_week_key
JOIN {{ ref('dim_product') }} AS p
  ON p.product_key = f.product_key
GROUP BY
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  p.category,
  p.subcategory,
  p.supplier_id,
  p.supplier_name
